use serde_json::{Value,json};use std::panic::{catch_unwind,AssertUnwindSafe};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");json!({"result":s.split(':').next().unwrap()})}}}
type BoxRef=Rc<RefCell<i32>>;
fn boxed(b:Option<&BoxRef>,slots:&[BoxRef])->Value{b.map_or(Value::Null,|b|json!({"id":slots.iter().position(|s|Rc::ptr_eq(s,b)).map_or(-1,|i|i as i32),"value":*b.borrow()}))}
fn sparse_state(m:&Rc<RefCell<SparseIndexMap<BoxRef>>>,probes:&Value,slots:&[BoxRef])->Value{json!({"first":m.borrow().getFirstIndex(),"last":m.borrow().getLastIndex(),"queries":probes.as_array().unwrap().iter().map(|n|call(||boxed(m.borrow().get(n.as_i64().unwrap()as i32),slots))).collect::<Vec<_>>()})}
fn sparse(h:&Value)->Value{let slots=[10,20,30,40].map(|n|Rc::new(RefCell::new(n)));let mut m=None;let made=call(||{m=Some(Rc::new(RefCell::new(SparseIndexMap::SparseIndexMap(h["max"].as_i64().unwrap()as i32))));});let mut out=json!({"made":made});let Some(m)=m else{return out;};let mut it=None;let mut held=None;let mut rows=vec![];for a in h["ops"].as_array().unwrap(){let c=call(||{let n=|i:usize|a[i].as_i64().unwrap()as i32;match a[0].as_str().unwrap(){"put"=>{held=m.borrow_mut().putNullable(n(1),if n(2)<0{None}else{Some(slots[n(2)as usize].clone())});boxed(held.as_ref(),&slots)},"get"=>{held=m.borrow().get(n(1)).cloned();boxed(held.as_ref(),&slots)},"remove"=>{held=m.borrow_mut().remove(n(1));boxed(held.as_ref(),&slots)},"mutate"=>{*slots[n(1)as usize].borrow_mut()=n(2);Value::Null},"heldMutate"=>{*held.as_ref().expect("NullPointerException").borrow_mut()=n(1);Value::Null},"iter"=>{let(first,last)=if a.as_array().unwrap().len()==1{let b=m.borrow();(b.getFirstIndex(),b.getLastIndex())}else{(n(1),n(2))};it=Some(IndexMapIterator::new(Some(m.clone()),first,last));Value::Null},"next"=>boxed(it.as_mut().expect("NullPointerException").next().as_ref(),&slots),"data"=>boxed(it.as_ref().expect("NullPointerException").data().as_ref(),&slots),"index"=>json!(it.as_ref().expect("NullPointerException").index()),"hasNext"=>json!(it.as_ref().expect("NullPointerException").hasNext()),"iterRemove"=>{it.as_ref().expect("NullPointerException").remove();Value::Null},_=>unreachable!()}});rows.push(json!({"call":c,"state":sparse_state(&m,&h["probes"],&slots),"held":boxed(held.as_ref(),&slots)}));}out["rows"]=json!(rows);out}
fn row_value(r:Option<Rc<KmoRowInfo>>)->Value{r.map_or(Value::Null,|r|row(&r))}
fn rows_state(m:&KmoRowInfos,probes:&Value)->Value{json!({"first":m.getFirstRow(),"last":m.getLastRow(),"queries":probes.as_array().unwrap().iter().map(|n|call(||row_value(m.getRowInfo(n.as_i64().unwrap()as i32)))).collect::<Vec<_>>(),"iterator":call(||{let mut out=vec![];let mut it=m.iterator();let mut count=0;while it.hasNext()&&count<100{count+=1;let old=it.index();let r=row_value(it.next());out.push(json!([old,r,it.index()]));}out})})}
fn pairs(mut it:super::super::KmoRowRange::KmoRowRangeIterator)->Value{let mut out=vec![];while it.hasNext(){let p=it.next();out.push(json!([p.first,p.second]));}json!(out)}
fn rows(h:&Value,sheet:&Rc<RefCell<KmoSheet>>)->Value{clear(&sheet.borrow());let m=KmoRowInfos::new(Rc::downgrade(sheet),sheet.borrow().getMaxRows());let other=KmoRowInfos::new(Rc::downgrade(sheet),sheet.borrow().getMaxRows());let slots=[Rc::new(KmoRowInfo::KmoRowInfo(1,300,15,256)),Rc::new(KmoRowInfo::KmoRowInfo(2,301,16,288)),Rc::new(KmoRowInfo::KmoRowInfo(1050,302,17,384))];let mut it=None;let mut held=None;let mut out=vec![];for a in h["ops"].as_array().unwrap(){let c=call(||{let n=|i:usize|a[i].as_i64().unwrap()as i32;match a[0].as_str().unwrap(){"set"=>m.setRowInfo(if n(1)<0{None}else{Some(slots[n(1)as usize].clone())}),"put"=>{held=m.put(n(1),if n(2)<0{None}else{Some(slots[n(2)as usize].clone())});return row_value(held.clone());},"get"=>{held=m.getRowInfo(n(1));return row_value(held.clone());},"remove"=>{held=m.remove(n(1));return row_value(held.clone());},"row"=>slots[n(1)as usize].setRowIndex(n(2)),"height"=>slots[n(1)as usize].setHeight(n(2)as i16),"flags"=>slots[n(1)as usize].setOptionFlags(n(2)as i16),"otherSet"=>other.setRowInfo(Some(slots[n(1)as usize].clone())),"copy"=>{other.copy(Some(&m));},"copyBack"=>{m.copy(Some(&other));},"copySelf"=>{m.copy(Some(&m));},"copyNull"=>{m.copy(None);},"iter"=>it=Some(if a.as_array().unwrap().len()==1{m.iterator()}else{m.iterator__range(n(1),n(2))}),"next"=>return row_value(it.as_mut().expect("NullPointerException").next()),"data"=>return row_value(it.as_ref().expect("NullPointerException").data()),"index"=>return json!(it.as_ref().expect("NullPointerException").index()),"hasNext"=>return json!(it.as_ref().expect("NullPointerException").hasNext()),"iterRemove"=>it.as_ref().expect("NullPointerException").remove(),_=>unreachable!()}Value::Null});out.push(json!({"call":c,"state":rows_state(&m,&h["probes"]),"other":rows_state(&other,&h["probes"]),"sameSlot":m.getRowInfo(1).is_some_and(|r|Rc::ptr_eq(&r,&slots[0])),"hidden":pairs(sheet.borrow().getHiddenRowsManager().iterator()),"operable":pairs(sheet.borrow().getOptHiddenRowColManager().rowIterator())}));}json!({"rows":out})}
fn fill(s:&Rc<RefCell<KmoSheet>>,a:&Value)->Value{let original=s.borrow().getRowInfos();json!(a.as_array().unwrap().iter().map(|op|{let n=|i:usize|op[i].as_i64().unwrap()as i32;let c=call(||s.borrow().initFillRowInfo(n(0),n(1)as i16,n(2)as i16,n(3)as i16));let probes=json!([n(0),n(0)&1048575]);json!({"call":c,"sameMap":Rc::ptr_eq(&s.borrow().getRowInfos(),&original),"state":rows_state(&s.borrow().getRowInfos(),&probes),"hidden":pairs(s.borrow().getHiddenRowsManager().iterator()),"operable":pairs(s.borrow().getOptHiddenRowColManager().rowIterator())})}).collect::<Vec<_>>())}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]fn original_android_sparse_maps_live_iterators_and_sheet_row_insertion(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/sparse-rows-r0b70");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let sheet=book.getActiveSheet();let sparse:Vec<_>=input["sparse"].as_array().unwrap().iter().map(sparse).collect();let rows:Vec<_>=input["rows"].as_array().unwrap().iter().map(|h|rows(h,&sheet)).collect();let actual=json!({"sparse":sparse,"rows":rows,"fill":fill(&sheet,&input["fill"])});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java,"root");}
